/**
 * Nuxt のモジュールが Nitro の中で使う関数。
 * 利用者の許可の関数は h3 の event を受け取るので、SDK が渡す Node の要求と応答から event を作って呼ぶ。
 * h3 は利用者のプロジェクトのものを使うため、createEvent と proxyRequest は Nitro の中の生成したコードから渡す
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import type { H3Event } from "h3";
import {
	allowBrowserAgents,
	type BrowserAuthorize,
	type BrowserPrincipal,
	isValidPrincipal,
	PRINCIPAL_HEADER,
} from "./access";

/** Nuxt の server/ に書く許可の関数。許すなら呼び出し元を返し、断るなら null を返す */
export type RouarAuthorize = (
	event: H3Event,
) =>
	| BrowserPrincipal
	| null
	| undefined
	| Promise<BrowserPrincipal | null | undefined>;

/** 許可の関数に型を付ける。中身はそのまま返す */
export function defineRouarAuthorize(
	authorize: RouarAuthorize,
): RouarAuthorize {
	return authorize;
}

type CreateEvent = (req: IncomingMessage, res: ServerResponse) => H3Event;

/** Nitro の外で作った event に、Nitro のユーティリティが読む context を足す */
function withNitroContext(event: H3Event): H3Event {
	const context = event.context as { nitro?: { errors: unknown[] } };
	context.nitro ??= { errors: [] };
	return event;
}

/**
 * h3 の event を受け取る許可の関数を、SDK の許可の関数に包む。
 * SDK のサーバーの入口は context.node に Node の要求と応答を入れて呼ぶ
 */
export function toBrowserAuthorize(
	authorize: RouarAuthorize,
	createEvent: CreateEvent,
): BrowserAuthorize {
	return (_request, context) => {
		if (!context.node) {
			throw new Error(
				"[rouar] The Nuxt authorize function needs the Node request. It runs only inside the rouar server.",
			);
		}
		return authorize(
			withNitroContext(createEvent(context.node.req, context.node.res)),
		);
	};
}

/** Nitro の起動のときに、許可の関数を SDK の登録先に入れる */
export function registerNuxtAuthorize(
	authorize: RouarAuthorize,
	createEvent: CreateEvent,
): void {
	allowBrowserAgents({ authorize: toBrowserAuthorize(authorize, createEvent) });
}

type ProxyRequest = (
	event: H3Event,
	target: string,
	options: { headers: Record<string, string> },
) => Promise<unknown>;

export type DevAgentProxyOptions = {
	/** 手元の Flue の開発のサーバーのオリジン */
	target: string;
	authorize?: RouarAuthorize;
	proxyRequest: ProxyRequest;
};

function problem(event: H3Event, status: number, title: string): string {
	event.node.res.statusCode = status;
	event.node.res.setHeader("content-type", "application/problem+json");
	return JSON.stringify({ type: "about:blank", title, status });
}

/**
 * 開発のときに、エージェントの経路への要求を手元の Flue の開発のサーバーへ中継する。
 * 許可の関数があれば中継の前に呼び、呼び出し元を x-rouar-principal で渡す。
 * 会話の id の書き換えと CSRF の確かめは、デプロイしたサーバーの入口だけが行う
 */
export async function handleDevAgentRequest(
	event: H3Event,
	options: DevAgentProxyOptions,
): Promise<unknown> {
	delete event.node.req.headers[PRINCIPAL_HEADER];
	const headers: Record<string, string> = {};
	if (options.authorize) {
		let result: BrowserPrincipal | null | undefined;
		try {
			result = await options.authorize(withNitroContext(event));
		} catch (error) {
			console.error("[rouar] the authorize function threw", error);
			return problem(event, 500, "Internal Server Error");
		}
		if (!result) return problem(event, 401, "Unauthorized");
		if (!isValidPrincipal(result.principal)) {
			console.error(
				"[rouar] the authorize function returned an invalid principal; use 1 to 256 printable ASCII characters",
			);
			return problem(event, 500, "Internal Server Error");
		}
		headers[PRINCIPAL_HEADER] = result.principal;
	}
	const path = event.path ?? event.node.req.url ?? "/";
	return options.proxyRequest(event, `${options.target}${path}`, { headers });
}
